package com.sora.splineroads.world;
import com.sora.splineroads.core.*;import com.sora.splineroads.core.RoadGeometry.*;import java.util.*;import java.io.*;import net.minecraft.nbt.*;import net.minecraft.core.*;
public class RetainedNode202Validation {
 static int checks;static void ok(boolean b,String t){checks++;if(!b)throw new AssertionError(t);}
 public static void main(String[]args)throws Exception{var tag=NbtIo.readCompressed(new File(args[0])).getCompound("data");var roads=new HashMap<UUID,RoadRecord>();for(Tag t:tag.getList("Roads",Tag.TAG_COMPOUND)){var r=RoadRecord.load((CompoundTag)t);roads.put(r.id(),r);}
 var lower=roads.get(UUID.fromString("3c13e036-ed13-4120-973b-f6e15c43f240"));var upper=roads.get(UUID.fromString("23f0d1c1-dbe9-4b43-b442-a23ae699c665"));var p=upper.a();var data=new RoadData();var before=new RoadIndex.Built(lower,true);var top=new RoadIndex.Built(upper,true);data.index.put(before);data.index.put(top);var next=new RoadIndex.Built(RoadRecord.load(lower.save()),true);var after=List.of(next,top);
 var method=RoadData.class.getDeclaredMethod("retainedNodeContact",BlockPos.class,RoadIndex.Built.class,List.class);method.setAccessible(true);
 ok(before.boxes(p).isEmpty()&&before.clearanceAt(p),"source fixture must match reported air-only old contact");ok((Boolean)method.invoke(data,p,next,after),"unchanged saved road contact rejected");
 var newId=new RoadRecord(UUID.randomUUID(),lower.owner(),lower.a(),lower.b(),lower.start(),lower.end(),lower.settings(),lower.automatic(),lower.clearance(),lower.structures(),lower.endCaps(),lower.buildVersion(),lower.assembly(),lower.alignment(),lower.furniturePhase(),lower.junction(),lower.toll(),lower.fragment());ok(!(Boolean)method.invoke(data,p,new RoadIndex.Built(newId,true),after),"new road identity accepted");ok(!(Boolean)method.invoke(data,p,next,List.of(next)),"removed endpoint owner accepted");
 var part=new RoadStructures.Part(new V(p.getX()+.5,p.getY(),p.getZ()+.5),new V(p.getX()+.5,p.getY(),p.getZ()+.5),.5,.5,true,RoadStructures.Material.CONCRETE);var parts=new ArrayList<>(lower.structures());parts.add(part);var added=new RoadIndex.Built(lower.structures(parts),true);ok(!added.boxes(p).isEmpty(),"added body fixture missing");ok(!(Boolean)method.invoke(data,p,added,List.of(added,top)),"new body accepted");
 data.index.remove(upper.id());ok(!(Boolean)method.invoke(data,p,next,after),"newly introduced owner accepted");data.index.put(top);var small=new RoadIndex.Built(lower.structures(List.of()),true);data.index.put(small);ok(!small.clearanceAt(p),"new clearance fixture invalid");ok(!(Boolean)method.invoke(data,p,next,after),"new air clearance accepted");
 System.out.println("SR202 RETAINED NODE PASS source="+p+" checks="+checks+" actual saved road geometry and strict identity/body/air negative controls");
 }
}
